#include <stdio.h>

int main() {
    int h[5] = {150, 142, 160, 138, 155};
    int n = 5;

    /* Swap two values with a temp */
    int a = 10, b = 20;
    int temp = a;
    a = b;
    b = temp;
    printf("a = %d, b = %d\n", a, b);

    /* One pass: compare neighbours, swap if out of order */
    for (int i = 0; i < n - 1; i++) {
        if (h[i] > h[i + 1]) {
            temp = h[i];
            h[i] = h[i + 1];
            h[i + 1] = temp;
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%d ", h[i]);
    }
    printf("\n");
    return 0;
}

